<?php
use App\Models\User;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Facades\Route;
Route::view('/','dashboard')->name('dashboard');Route::get('/login',fn()=>view('login'))->name('login');Route::get('/register',fn()=>view('register'))->name('register');Route::post('/register',function(\Illuminate\Http\Request $r){$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|max:255|unique:users,email','password'=>'required|string|min:8']);$u=User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password'])]);auth()->login($u);$r->session()->regenerate();return redirect('/');})->name('register.store');Route::post('/login',function(\Illuminate\Http\Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required']);if(!auth()->attempt($c))return back()->withErrors(['email'=>'Invalid credentials.']);$r->session()->regenerate();return redirect('/');})->name('login.store');Route::post('/logout',function(\Illuminate\Http\Request $r){auth()->logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');})->name('logout');